<?php
use Illuminate\Support\Facades\Route;use App\Http\Controllers\{AdminAuthController,OperationsController,ProjectController,FileController,ContentController};use Illuminate\Foundation\Http\Middleware\ValidateCsrfToken;
Route::get('/admin/login',fn()=>response()->file(config('northbyte.root').'/admin-ui/login.html'))->name('login');
Route::prefix('api/admin')->group(function(){
 Route::post('login',[AdminAuthController::class,'login'])->middleware('throttle:admin-login');
 Route::post('forgot-password',[AdminAuthController::class,'forgot'])->middleware('throttle:5,10');
 Route::post('reset-password',[AdminAuthController::class,'reset'])->middleware('throttle:5,10');
 Route::middleware(['auth:sanctum','admin.session','admin','throttle:240,1'])->group(function(){
  Route::get('session',[AdminAuthController::class,'session']);Route::post('logout',[AdminAuthController::class,'logout']);Route::patch('profile',[AdminAuthController::class,'profile']);Route::get('lookup',[OperationsController::class,'lookup']);
  Route::get('overview',[OperationsController::class,'overview'])->middleware('admin:dashboard');
  Route::get('clients',[OperationsController::class,'clients'])->middleware('admin:clients');Route::get('clients/{client}',[OperationsController::class,'client'])->middleware('admin:clients');Route::patch('clients/{client}',[OperationsController::class,'updateClient'])->middleware('admin:clients');Route::post('clients/{client}/notes',[OperationsController::class,'clientNote'])->middleware('admin:clients');
  Route::get('projects',[ProjectController::class,'index'])->middleware('admin:projects');Route::post('projects',[ProjectController::class,'store'])->middleware('admin:projects');Route::get('projects/{project}',[ProjectController::class,'show'])->middleware('admin:projects');Route::patch('projects/{project}',[ProjectController::class,'update'])->middleware('admin:projects');Route::post('projects/{project}/milestones',[ProjectController::class,'milestone'])->middleware('admin:projects');Route::post('projects/{project}/notes',[ProjectController::class,'note'])->middleware('admin:projects');Route::post('projects/{project}/discuss',[ProjectController::class,'discuss'])->middleware('admin:messages');
  Route::get('files',[FileController::class,'index'])->middleware('admin:files');Route::post('projects/{project}/files',[FileController::class,'upload'])->middleware('admin:files');Route::get('files/{file}',[FileController::class,'download'])->middleware('admin:files');Route::delete('files/{file}',[FileController::class,'destroy'])->middleware('admin:files');
  Route::get('team',[OperationsController::class,'team'])->middleware('admin:team');Route::post('team',[OperationsController::class,'saveTeam'])->middleware('admin:team');Route::patch('team/{member}',[OperationsController::class,'saveTeam'])->middleware('admin:team');
  Route::get('notifications',[OperationsController::class,'notifications'])->middleware('admin:notifications');Route::post('notifications/read',[OperationsController::class,'readNotifications'])->middleware('admin:notifications');Route::get('activity-logs',[OperationsController::class,'logs'])->middleware('admin:activity');
  Route::get('settings',[OperationsController::class,'settings'])->middleware('admin:settings');Route::put('settings',[OperationsController::class,'saveSettings'])->middleware('admin:settings');Route::get('content',[ContentController::class,'index'])->middleware('admin:content');Route::put('content/{key}',[ContentController::class,'save'])->middleware('admin:content');Route::post('content/{key}/publish',[ContentController::class,'publish'])->middleware('admin:content');
 });
});
Route::middleware(['auth:sanctum','admin.session','admin'])->group(function(){Route::get('/admin',fn()=>redirect('/admin/dashboard'));Route::get('/admin/{page?}',function(string $page='dashboard'){$cap=match(explode('/',$page)[0]){'activity-logs'=>'activity',default=>explode('/',$page)[0]};abort_unless(in_array($cap,['dashboard','clients','projects','messages','files','team','content','notifications','activity','settings']),404);abort_unless(request()->user()->allows($cap)||$cap==='settings',403);return response()->file(config('northbyte.root').'/admin-ui/index.html');})->where('page','.*');});
Route::get('/api/public/content',fn(ContentController $c)=>response()->json($c->publicData())->header('Cache-Control','public, max-age=60'));
Route::prefix('api/client')->middleware('client.session')->withoutMiddleware(ValidateCsrfToken::class)->group(function(){Route::get('projects',[ProjectController::class,'index']);Route::post('projects',[ProjectController::class,'store']);Route::post('projects/import',[ProjectController::class,'importLegacy']);Route::get('projects/{project}',[ProjectController::class,'show']);Route::post('projects/{project}/discuss',[ProjectController::class,'discuss']);Route::post('projects/{project}/files',[FileController::class,'upload']);Route::get('files/{file}',[FileController::class,'download']);});
